import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the preprocessing step
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output directories
    WORKING_DIR = "./working"
    # Cache directory for processed data (e.g. parsed geometries)
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data Configuration
    # -------------------------------------------------------------------------
    # Atomic species mapping
    ATOM_MAP = {"Al": 0, "Ga": 1, "In": 2, "O": 3}
    NUM_ATOM_TYPES = 4

    # Tabular features to use:
    # Lattice vectors (3), Angles (3), Total atoms (1), Composition (3)
    TABULAR_FEATURE_COLS = [
        "lattice_vector_1_ang",
        "lattice_vector_2_ang",
        "lattice_vector_3_ang",
        "lattice_angle_alpha_degree",
        "lattice_angle_beta_degree",
        "lattice_angle_gamma_degree",
        "number_of_total_atoms",
        "percent_atom_al",
        "percent_atom_ga",
        "percent_atom_in",
    ]
    NUM_TABULAR_FEATURES = len(TABULAR_FEATURE_COLS)

    # Targets
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters (LCDS)
    # -------------------------------------------------------------------------
    # Atomic Branch (Deep Sets)
    # Input: 3 (Cartesian coords) + 4 (One-hot encoded atom type)
    ATOMIC_INPUT_DIM = 3 + NUM_ATOM_TYPES
    # MLP layers for processing individual atoms before pooling
    ATOMIC_HIDDEN_DIMS = [128, 256]
    # Dimension of the global geometric fingerprint.
    # Note: We will use Dual Pooling (Mean + Max), so actual output will be 2x this.
    ATOMIC_LATENT_DIM = 256

    # Lattice Branch
    # Input: Macroscopic tabular features
    LATTICE_INPUT_DIM = NUM_TABULAR_FEATURES
    # MLP layers for processing lattice features - Increased capacity
    LATTICE_HIDDEN_DIMS = [64, 128]
    LATTICE_LATENT_DIM = 128

    # Fusion & Prediction
    # Concatenated dimension: (Atomic Latent * 2) + Lattice Latent
    FUSION_INPUT_DIM = (ATOMIC_LATENT_DIM * 2) + LATTICE_LATENT_DIM
    # Final regressor MLP layers
    FUSION_HIDDEN_DIMS = [256, 128]
    OUTPUT_DIM = 2  # Predicting 2 targets

    DROPOUT_RATE = 0.1

    # -------------------------------------------------------------------------
    # Training Configuration
    # -------------------------------------------------------------------------
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 300
    EARLY_STOPPING_PATIENCE = 30

    # Debugging / Development
    # Set DEBUG to True to run on a small subset of data for quick testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100  # Number of samples to use in debug mode

    # Compute
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # For data loading

    @classmethod
    def setup(cls):
        """Create necessary output directories."""
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
